import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:somnia/services/audio_event_classifier.dart';
import 'package:somnia/services/sleep_audio_model.dart';

import 'support/audio_fixtures.dart';

/// Dart and Python feature extractors must agree: relative error <= 1e-3.
///
/// Fixtures are generated by `python -m tools.somnia_audio.make_fixtures`.
void main() {
  final Map<String, dynamic> manifest = loadAudioFixtureManifest();
  final List<dynamic> clips = manifest['clips'] as List<dynamic>;
  const String directory = kAudioFixtureDirectory;

  Uint8List readWav(String path) => readWavPcm(path);

  test('фикстуры описывают 4 класса и 34 признака', () {
    expect(clips, hasLength(4));
    expect(manifest['feature_names'], hasLength(34));
  });

  for (final dynamic raw in clips) {
    final Map<String, dynamic> clip = raw as Map<String, dynamic>;
    final String name = clip['file'] as String;

    test('признаки Dart совпадают с Python: $name', () {
      final AudioFeatures features = AudioEventClassifier.analyzeFeatures(
        readWav('$directory/$name'),
      );
      final Map<String, dynamic> expected =
          clip['features'] as Map<String, dynamic>;

      for (final String feature in manifest['feature_names'] as List<dynamic>) {
        final int featureIndex = kSleepAudioFeatureNames.indexOf(feature);
        expect(featureIndex, isNonNegative, reason: 'unknown $feature');
        final double actual = features.toVector()[featureIndex];
        final double reference = (expected[feature] as num).toDouble();
        double tolerance = 1e-3 * (reference.abs() > 1 ? reference.abs() : 1.0);
        // Percentile-based IQR of a narrow centroid distribution is
        // rank-sensitive: a float rounding difference can shift the quartile
        // by one sample. Absolute error is still < 0.5 Hz.
        if (feature.endsWith('_iqr_hz')) {
          tolerance = tolerance < 0.5 ? 0.5 : tolerance;
        }
        expect(
          (actual - reference).abs(),
          lessThanOrEqualTo(tolerance),
          reason: '$name.$feature: dart=$actual python=$reference',
        );
      }
    });

    test('вероятности и класс совпадают с Python: $name', () {
      final AudioClassification result =
          AudioEventClassifier.classify(readWav('$directory/$name'));
      final Map<String, dynamic> expected =
          clip['probabilities'] as Map<String, dynamic>;

      result.probabilities.forEach((type, probability) {
        final double reference = (expected[type.name] as num).toDouble();
        expect(
          (probability - reference).abs(),
          lessThan(1e-3),
          reason: '$name.${type.name}: dart=$probability python=$reference',
        );
      });
      expect(result.type.name, clip['expected_type']);
    });
  }

  test('асинхронная классификация даёт тот же результат', () async {
    final Uint8List pcm = readWav('$directory/snore.wav');
    final AudioClassification sync = AudioEventClassifier.classify(pcm);
    final AudioClassification async =
        await AudioEventClassifier.classifyAsync(pcm);
    expect(async.type, sync.type);
    expect(async.confidence, closeTo(sync.confidence, 1e-9));
    expect(async.segments.length, sync.segments.length);
  });

  test('сегменты покрывают клип без разрывов', () {
    final AudioClassification result = AudioEventClassifier.classify(
      readWav('$directory/talk.wav'),
    );
    expect(result.segments, isNotEmpty);
    expect(result.segments.first.startMs, 0);
    for (var i = 1; i < result.segments.length; i++) {
      expect(
        result.segments[i].startMs,
        lessThanOrEqualTo(result.segments[i - 1].endMs + 250),
      );
    }
  });
}
